<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuth} from '../../entities/auth/model'
import {request,errorMessage,isCancelled} from '../../shared/api/client'
import type {CallDetail,Taxonomy,Evidence} from '../../shared/interfaces'
import {datetime,duration,resultLabels,stageLabels,kindLabels,text,providerCost} from '../../shared/lib/format'
import Icon from '../../shared/ui/Icon.vue'
import Empty from '../../shared/ui/Empty.vue'
import Notice from '../../shared/ui/Notice.vue'
import ProcessingPanel from '../../features/processing/ProcessingPanel.vue'
import {isActive} from '../../shared/lib/processing'
import AudioPlayer from '../../features/audio-player/AudioPlayer.vue'
const auth=useAuth(),route=useRoute(),router=useRouter(),detail=ref<CallDetail|null>(null),taxonomy=ref<Taxonomy>({tags:[],statuses:[]}),loading=ref(true),error=ref(''),success=ref(''),tab=ref('transcript'),note=ref(''),status=ref<string|null>(null),tags=ref<string[]>([]),kind=ref('unknown'),locked=ref(true),saving=ref(false),dirty=ref(false),editVersion=ref(0),seek=ref<number>(),seekVersion=ref(0),selectedAnalysis=ref(''),selectedTranscript=ref(''),highlight=ref(''),confirmDelete=ref(false),dealModal=ref(false),contactId=ref(''),dealId=ref(''),deals=ref<Record<string,unknown>[]>([]),contacts=ref<Record<string,unknown>[]>([]),roleModal=ref(false),roleMap=ref<Record<string,string>>({}),roleSpeakers=ref<string[]>([]),roleTranscriptId=ref(''),reprocessing=ref(false)
let timer:ReturnType<typeof setInterval>|undefined
const id=computed(()=>String(route.params.id)),call=computed(()=>detail.value?.call),transcript=computed(()=>detail.value?.transcripts.find(t=>t.id===selectedTranscript.value)||detail.value?.transcripts[0]),analysis=computed(()=>selectedAnalysis.value?detail.value?.analyses.find(a=>a.id===selectedAnalysis.value):detail.value?.analyses.find(a=>a.transcript_id===detail.value?.transcripts[0]?.id&&['ready','partial'].includes(a.state))||(!call.value?.analysis_state?detail.value?.analyses[0]:undefined)),historicalAnalysis=computed(()=>!!analysis.value&&!!detail.value?.transcripts.length&&analysis.value.transcript_id!==detail.value.transcripts[0]?.id)
async function load(background=false){if(!background)loading.value=true;try{const[d,t]=await Promise.all([request<CallDetail>('/calls/'+id.value),request<Taxonomy>('/taxonomy')]);detail.value=d;taxonomy.value=t;if(!dirty.value){note.value=d.call.note||'';status.value=d.call.status_id;tags.value=[...d.call.tag_ids];kind.value=d.call.contact_kind;locked.value=d.call.manual_lock;editVersion.value=d.call.version}error.value=''}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{loading.value=false}}
function toggleTag(tag:string){tags.value=tags.value.includes(tag)?tags.value.filter(t=>t!==tag):[...tags.value,tag];dirty.value=true}
async function save(){if(!call.value)return;saving.value=true;error.value='';try{await request('/calls/'+id.value,{method:'PATCH',body:{status_id:status.value||null,tag_ids:tags.value,note:note.value,contact_kind:kind.value,manual_lock:locked.value,version:editVersion.value}});dirty.value=false;success.value='Изменения сохранены';await load(true)}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
async function discard(){dirty.value=false;await load()}
function canProcess(stage:string){if(reprocessing.value||isActive(detail.value?.processing))return false;const p=detail.value?.processing;if(!p)return stage==='analyze'?!!detail.value?.transcripts.length:!!call.value?.has_recording;if(stage==='analyze')return call.value?.transcript_state==='ready'&&p.providers.analysis.ready;return call.value?.recording_state==='ready'&&p.providers.asr.ready&&(stage!=='all'||p.providers.analysis.ready)}
async function reprocess(stage:string){if(!canProcess(stage))return;reprocessing.value=true;error.value='';success.value='';try{const result=await request<{job_id:string;reused?:boolean}>('/calls/'+id.value+'/reprocess',{method:'POST',body:{stage}});success.value=result.reused?'Этот разговор уже обрабатывается. Состояние показано ниже.':'Задание принято. Следи за этапами и очередью ниже.';await load(true)}catch(e){if(!isCancelled(e))error.value=errorMessage(e)}finally{reprocessing.value=false}}
function jump(time:number){seek.value=time;seekVersion.value++}
function evidence(value:Evidence){jump(value.start);highlight.value=value.segment_id;tab.value='transcript';setTimeout(()=>document.getElementById('segment-'+value.segment_id)?.scrollIntoView({behavior:'smooth',block:'center'}),50)}
function assignRoles(){if(!transcript.value)return;roleTranscriptId.value=transcript.value.id;roleSpeakers.value=[...new Set(transcript.value.segments.map(segment=>segment.speaker).filter(speaker=>typeof speaker==='string'&&speaker.trim().length>0))];roleMap.value=Object.fromEntries(roleSpeakers.value.map(speaker=>[speaker,transcript.value!.segments.find(s=>s.speaker===speaker)?.role||'unknown']));roleModal.value=true}
async function saveRoles(){saving.value=true;try{const roles=Object.fromEntries(roleSpeakers.value.map(speaker=>[speaker,roleMap.value[speaker]||'unknown']));const result=await request<{transcript:{id:string};job_id:string}>('/calls/'+id.value+'/transcripts/'+roleTranscriptId.value+'/roles',{method:'POST',body:{roles}});selectedTranscript.value=result.transcript.id;roleModal.value=false;success.value='Роли сохранены в новой версии. Анализ поставлен в очередь.';await load(true)}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
async function remove(){try{await request('/calls/'+id.value,{method:'DELETE'});await router.replace('/calls')}catch(e){error.value=errorMessage(e)}finally{confirmDelete.value=false}}
async function searchDeals(){try{const result=await request<{contacts:Record<string,unknown>[];deals:Record<string,unknown>[]}>('/integrations/amocrm/search?phone='+encodeURIComponent(call.value?.phone||''));deals.value=result.deals;contacts.value=result.contacts}catch(e){error.value=errorMessage(e)}}
async function linkDeal(){try{if(!contactId.value||!dealId.value)throw Error('Укажите контакт и сделку');await request('/integrations/link',{method:'POST',body:{call_id:id.value,provider:'amocrm',contact_id:contactId.value,deal_id:dealId.value}});dealModal.value=false;success.value='Сделка привязана';await load(true)}catch(e){error.value=errorMessage(e)}}
async function publish(provider:string){try{await request('/integrations/export',{method:'POST',body:{call_ids:[id.value],provider}});success.value='Отправка поставлена в очередь'}catch(e){error.value=errorMessage(e)}}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load(true)},15000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><RouterLink class="text-link" to="/calls" style="display:inline-block;margin-bottom:20px">← Вернуться к звонкам</RouterLink><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><Empty v-if="loading&&!detail" loading/>
<template v-else-if="detail&&call"><div class="page-heading"><div class="detail-top" style="margin:0"><div class="contact-avatar">{{(call.contact_name||'К').slice(0,1)}}</div><div><h1>{{call.contact_name||call.phone||'Скрытый номер'}}</h1><p>{{call.phone}} · {{datetime(call.started_at,auth.me?.organization.timezone)}} · {{call.employee||'Сотрудник не определён'}}</p></div></div><div class="heading-actions"><button class="button" @click="load()"><Icon name="refresh" :size="14"/>Обновить</button><button v-if="auth.canWrite" class="button primary" :disabled="!canProcess('all')" @click="reprocess('all')"><Icon name="activity" :size="15"/>Повторить обработку</button></div></div>
<div class="inline-labels" style="margin-bottom:22px"><span class="badge" :class="call.human_connected?'teal':'amber'">{{resultLabels[call.provider_result]||call.provider_result}}</span><span class="badge outline">{{stageLabels[call.stage]||call.stage}}</span><span class="badge blue">{{kindLabels[call.contact_kind]||'Не определено'}}</span><span class="badge outline">{{duration(call.duration)}}</span><span v-if="call.manual_lock" class="badge purple"><Icon name="lock" :size="11"/>Ручная разметка защищена</span></div>
<Notice v-if="!call.coverage_complete" message="История контакта неполная. Первичность обращения и отсутствие перезвона могут быть не определены."/>
<ProcessingPanel :call="call" :processing="detail.processing" :timezone="auth.me?.organization.timezone" :owner="auth.isOwner"/><div class="detail-grid"><div class="stack"><div class="card"><AudioPlayer :call-id="call.id" :recordings="detail.recordings" :seek-to="seek" :seek-version="seekVersion"/><div class="tabs"><button :class="{active:tab==='transcript'}" @click="tab='transcript'">Расшифровка <span class="tab-count">{{detail.transcripts.length}}</span></button><button :class="{active:tab==='analysis'}" @click="tab='analysis'">Анализ диалога <span class="tab-count">{{detail.analyses.length}}</span></button><button :class="{active:tab==='history'}" @click="tab='history'">История клиента</button><button :class="{active:tab==='technical'}" @click="tab='technical'">Детали</button></div>
<div v-if="tab==='transcript'" class="card-body"><template v-if="transcript"><div class="section-title"><span class="badge" :class="transcript.role_confidence==='known'?'teal':'amber'">{{transcript.role_confidence==='known'?'Роли участников определены':'Роли участников требуют проверки'}}</span><button v-if="transcript.role_confidence!=='known'&&auth.canWrite" class="button small" @click="assignRoles">Назначить роли</button><select v-if="detail.transcripts.length>1" v-model="selectedTranscript" aria-label="Версия расшифровки"><option value="">Последняя версия</option><option v-for="t in detail.transcripts" :key="t.id" :value="t.id">Версия {{t.version}} · {{t.provider}}</option></select><span v-else class="subtle">Версия {{transcript.version}} · {{transcript.provider}}</span></div><div v-for="segment in transcript.segments" :key="segment.id" :id="'segment-'+segment.id" class="segment" :class="{active:highlight===segment.id}"><button class="segment-time" @click="jump(segment.start)">{{duration(segment.start)}}</button><div><div class="segment-speaker">{{segment.role==='manager'?'Сотрудник':segment.role==='client'?'Клиент':segment.speaker||'Участник'}}</div><p>{{segment.text}}</p></div></div><Empty v-if="!transcript.segments.length" title="Нет распознанного текста" description="Обработка могла завершиться без речи или с недостаточным качеством звука."/></template><Empty v-else title="Расшифровка ещё не готова" :description="call.has_recording?'Состояние этапа и причины ожидания показаны в блоке «Обработка разговора».':'Для расшифровки нужна доступная запись разговора.'"><button v-if="auth.canWrite&&call.has_recording" class="button" :disabled="!canProcess('transcribe')" @click="reprocess('transcribe')">Расшифровать запись</button></Empty></div>
<div v-else-if="tab==='analysis'" class="card-body"><div v-if="detail.analyses.length" class="section-title"><label>Версия анализа <select v-model="selectedAnalysis" aria-label="Версия анализа"><option value="">Актуальный анализ</option><option v-for="a in detail.analyses" :key="a.id" :value="a.id">{{a.transcript_id!==detail.transcripts[0]?.id?'Предыдущий анализ — ':''}}{{datetime(a.created_at)}} · {{a.model}}</option></select></label></div><Notice v-if="historicalAnalysis" message="Показан предыдущий анализ: он относится к другой версии расшифровки."/><template v-if="analysis"><div class="section-title"><div><span class="score-large">{{analysis.score===null?'—':Math.round(analysis.score)}}<small> / 100</small></span><p class="subtle" style="margin:8px 0 0">{{analysis.model}} · версия критериев {{analysis.rubric_version}}</p></div></div><Notice v-if="analysis.abstention_reason" :message="analysis.abstention_reason"/><h4>Что произошло в разговоре</h4><p style="font-size:12px;line-height:1.8;color:#71898b">{{analysis.summary||'Резюме не сформировано'}}</p><div v-if="analysis.customer_intent" class="notice info">Запрос клиента: {{analysis.customer_intent}}</div><div class="grid-even" style="margin-bottom:22px"><div><h4>Договорённости</h4><div v-for="(item,i) in analysis.agreements" :key="i" class="bullet-item">{{item}}</div><p v-if="!analysis.agreements.length" class="subtle">Не зафиксированы</p></div><div><h4>Следующие шаги</h4><div v-for="(item,i) in analysis.next_steps" :key="i" class="bullet-item">{{item}}</div><p v-if="!analysis.next_steps.length" class="subtle">Не определены</p></div></div><h4>Оценка по критериям</h4><div v-for="criterion in analysis.criteria" :key="criterion.id" class="criterion"><div class="criterion-title"><b>{{criterion.name}}</b><span v-if="criterion.evaluation_mode==='checklist'" class="badge" :class="criterion.fulfilled===true?'teal':criterion.fulfilled===false?'red':'outline'">{{criterion.status==='not_applicable'?'Неприменимо':criterion.fulfilled===true?'Да':criterion.fulfilled===false?'Нет':'Недостаточно данных'}}</span><span v-else class="score" :class="criterion.score===null?'unknown':criterion.score<3?'medium':''">{{criterion.score===null?'—':criterion.score}}<span v-if="criterion.score!==null"> / 5</span></span></div><p>{{criterion.reason||({not_applicable:'Критерий неприменим',insufficient_evidence:'Недостаточно доказательств'} as Record<string,string>)[criterion.status]}}</p><button v-for="(proof,i) in criterion.evidence" :key="i" class="evidence" @click="evidence(proof)"><span class="subtle">{{duration(proof.start)}} · перейти к фрагменту</span><br>«{{proof.quote}}»</button></div><div class="divider"></div><p class="subtle">Результаты анализа — подсказка для проверки разговора. {{analysis.usage.input_tokens+analysis.usage.output_tokens}} токенов · стоимость {{providerCost(analysis.usage.cost)}}</p></template><Empty v-else title="Диалог ещё не оценён" description="После расшифровки модель оценит разговор по настроенным критериям."><button v-if="auth.canWrite&&detail.transcripts.length" class="button" :disabled="!canProcess('analyze')" @click="reprocess('analyze')">Проанализировать диалог</button></Empty></div>
<div v-else-if="tab==='history'" class="card-body"><h4>Другие обращения этого контакта</h4><ul v-if="detail.history.length" class="list-clean"><li v-for="item in detail.history" :key="item.id"><RouterLink :to="'/calls/'+item.id" class="section-title" style="margin:0"><span>{{datetime(item.started_at,auth.me?.organization.timezone)}}<br><span class="subtle">{{item.employee||'Без сотрудника'}} · {{duration(item.duration)}}</span></span><span class="badge">{{resultLabels[item.provider_result]||item.provider_result}}</span><Icon name="chevron" :size="14"/></RouterLink></li></ul><Empty v-else title="Других звонков не найдено" description="Это первое наблюдаемое обращение в доступной истории. Оно не обязательно первичное для компании."/></div>
<div v-else class="card-body"><h4>Маршрут и составные части</h4><div v-for="(leg,i) in detail.legs" :key="i" class="criterion"><div class="section-title"><b>Плечо {{i+1}}</b><span class="badge">{{text(leg.result||leg.flow)}}</span></div><dl class="meta-list"><div v-for="field in ['extension_name','extension_id','init_time_gmt','start_time_gmt','duration']" :key="field"><dt>{{field}}</dt><dd>{{text(leg[field])}}</dd></div></dl></div><p v-if="!detail.legs.length" class="subtle">Данные плеч отсутствуют.</p><div class="divider"></div><h4>История изменений</h4><ul class="list-clean"><li v-for="(event,i) in detail.audit" :key="i">{{text(event.action||event.kind||event.event_type)}}<small class="subtle"> · {{datetime(event.created_at)}} · {{text(event.actor||event.user_id)}}</small></li></ul></div></div></div>
<aside class="detail-aside stack"><div class="card"><div class="card-header"><h3>Разметка и заметки</h3><Icon name="tag" :size="15" style="color:#a4b7b0"/></div><div class="card-body detail-note"><label>Бизнес-статус<select v-model="status" :disabled="!auth.canWrite" @change="dirty=true"><option :value="null">Не назначен</option><option v-for="s in taxonomy.statuses.filter(s=>!s.archived||s.id===status)" :key="s.id" :value="s.id">{{s.name}}{{s.archived?' (архив)':''}}</option></select></label><label style="margin-top:17px">Тип обращения<select v-model="kind" :disabled="!auth.canWrite" @change="dirty=true"><option v-for="(label,value) in kindLabels" :key="value" :value="value">{{label}}</option></select></label><div class="small-heading" style="margin-top:20px;margin-bottom:9px">Теги</div><div class="inline-labels"><button v-for="tag in taxonomy.tags.filter(t=>!t.archived||tags.includes(t.id))" :key="tag.id" class="tag-toggle" :class="{selected:tags.includes(tag.id)}" :disabled="!auth.canWrite" @click="toggleTag(tag.id)">{{tag.name}}{{tag.archived?' (архив)':''}}</button><span v-if="!taxonomy.tags.length" class="subtle">Добавьте теги в настройках</span></div><label style="margin-top:18px">Заметка<textarea v-model="note" :disabled="!auth.canWrite" placeholder="Что важно учесть при следующем контакте" @input="dirty=true"></textarea></label><label class="checkbox" style="margin-top:13px;font-size:9px"><input v-model="locked" type="checkbox" :disabled="!auth.canWrite" @change="dirty=true"/>Защитить разметку от автоматической замены</label><button v-if="auth.canWrite" class="button primary full" style="margin-top:18px" :disabled="saving||!dirty" @click="save">{{saving?'Сохраняем…':'Сохранить изменения'}}</button><button v-if="auth.canWrite&&dirty" class="button full small" style="margin-top:8px" @click="discard">Сбросить несохранённое</button></div></div>
<div class="card"><div class="card-header"><h3>Информация о звонке</h3></div><div class="card-body"><dl class="meta-list"><div><dt>Направление</dt><dd>{{call.direction==='in'?'Входящий':call.direction==='out'?'Исходящий':'Внутренний'}}</dd></div><div><dt>Сотрудник</dt><dd>{{call.employee||'Не определён'}}</dd></div><div><dt>Разговор с человеком</dt><dd>{{call.human_connected?'Подтверждён':'Не подтверждён'}}</dd></div><div><dt>История контакта</dt><dd>{{call.coverage_complete?'Полная':'Частичная'}}</dd></div><div><dt>Версия записи</dt><dd>{{call.version}}</dd></div></dl></div></div>
<div class="card"><div class="card-header"><h3>Связь со сделкой</h3></div><div class="card-body"><ul class="list-clean"><li v-for="(link,i) in detail.external_links" :key="i">{{text(link.provider)}} · {{text(link.deal_id||link.external_id||link.id)}}</li></ul><p v-if="!detail.external_links.length" class="subtle">Звонок пока не привязан к сделке. Неоднозначное совпадение выбирается вручную.</p><div v-if="auth.canWrite" class="stack" style="gap:8px"><button class="button" @click="dealModal=true">Привязать amoCRM</button><button class="button small" @click="publish('amocrm')">Отправить результат в amoCRM</button><button class="button small" @click="publish('sheets')">Отправить в Google Таблицы</button></div></div></div><button v-if="auth.isOwner" class="button danger" @click="confirmDelete=true">Удалить звонок и данные</button></aside></div>
</template><Empty v-else title="Звонок недоступен" description="Возможно, он удалён или находится в другой компании."/>
<div v-if="dealModal" class="modal-shade" @click.self="dealModal=false"><section class="modal" role="dialog" aria-modal="true" aria-label="Привязка сделки"><div class="modal-header"><h2>Привязать сделку amoCRM</h2><button class="icon-button" aria-label="Закрыть" @click="dealModal=false"><Icon name="close"/></button></div><form @submit.prevent="linkDeal"><div class="modal-body"><p class="muted">Выберите контакт и сделку для этого звонка. Система не выбирает случайное совпадение.</p><button type="button" class="button" @click="searchDeals">Найти по номеру клиента</button><div class="form-grid" style="margin-top:18px"><label>ID контакта<input v-model="contactId" required list="contacts"/><datalist id="contacts"><option v-for="(c,i) in contacts" :key="i" :value="String(c.id)">{{c.name}}</option></datalist></label><label>ID сделки<input v-model="dealId" required list="deals"/><datalist id="deals"><option v-for="(d,i) in deals" :key="i" :value="String(d.id)">{{d.name}}</option></datalist></label></div></div><div class="modal-footer"><button type="button" class="button" @click="dealModal=false">Отмена</button><button class="button primary">Привязать</button></div></form></section></div>
<div v-if="roleModal" class="modal-shade" @click.self="roleModal=false"><section class="modal" role="dialog" aria-modal="true" aria-label="Назначить роли участников"><div class="modal-header"><h2>Кто участвовал в разговоре?</h2><button class="icon-button" aria-label="Закрыть" @click="roleModal=false"><Icon name="close"/></button></div><form @submit.prevent="saveRoles"><div class="modal-body role-assignment"><p class="muted">Сопоставьте участников с ролями. Исходная расшифровка сохранится; после подтверждения создастся новая версия и повторный анализ.</p><div class="form-grid"><label v-for="speaker in roleSpeakers" :key="speaker">Участник {{speaker}}<select v-model="roleMap[speaker]"><option value="unknown">Не определено</option><option value="manager">Сотрудник</option><option value="client">Клиент</option></select></label></div><p v-if="!roleSpeakers.length" class="notice info">В этой расшифровке нет идентификаторов участников. Уточните источник распознавания.</p></div><div class="modal-footer"><button type="button" class="button" @click="roleModal=false">Отмена</button><button class="button primary" :disabled="saving||!roleSpeakers.length">Сохранить роли и анализировать</button></div></form></section></div>
<div v-if="confirmDelete" class="modal-shade" @click.self="confirmDelete=false"><section class="modal" role="dialog" aria-modal="true" aria-label="Удаление звонка"><div class="modal-body"><h2>Удалить звонок?</h2><p class="muted">Запись, расшифровки и анализы будут отправлены на удаление. Действие нельзя отменить.</p><div class="form-actions"><button class="button" @click="confirmDelete=false">Отмена</button><button class="button danger" @click="remove">Удалить данные</button></div></div></section></div>
</template>
